const nameEl = document.getElementById('name');
const valueEl = document.getElementById('value');
const msgEl = document.getElementById('msg');
const listEl = document.getElementById('list');
const totalEl = document.getElementById('total');
const chartEl = document.getElementById('chart');
const emptyEl = document.getElementById('empty');
const typeEl = document.getElementById('ctype');
let items = [];
const revs = new Map();

function say(text, kind) {
  msgEl.textContent = text;
  msgEl.className = 'msg ' + (kind || '');
}

function render() {
  let total = 0;
  for (const it of items) total += it.amount;
  total = Math.round(total * 100) / 100;
  totalEl.textContent = String(total);
  listEl.textContent = '';
  for (const it of items) {
    const li = document.createElement('li');
    const n = document.createElement('span');
    n.className = 'n';
    n.textContent = it.name;
    const a = document.createElement('span');
    a.textContent = String(it.amount);
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'secondary';
    b.textContent = 'Remove';
    b.setAttribute('aria-label', 'Remove ' + it.name);
    b.addEventListener('click', () => removeItem(it.id));
    li.append(n, a, b);
    listEl.appendChild(li);
  }
  emptyEl.hidden = items.length > 0;
  chartEl.hidden = items.length === 0;
  if (items.length > 0) {
    const labels = [];
    const values = [];
    for (const it of items) { labels.push(it.name.slice(0, 80)); values.push(it.amount); }
    tessera.chart(chartEl, {
      type: typeEl.value,
      title: 'Spending this month',
      labels: labels,
      series: [{ name: 'Amount', values: values }]
    });
  }
}

async function load() {
  const res = await tessera.call('data.read', {});
  const list = Array.isArray(res.data.expenses) ? res.data.expenses : [];
  items = [];
  for (const r of list) {
    items.push({ id: r.id, name: String(r.name), amount: Number(r.amount) || 0 });
  }
  revs.clear();
  for (const [id, rev] of Object.entries(res.revisions.expenses || {})) revs.set(id, rev);
  render();
}

async function addItem() {
  const name = nameEl.value.trim();
  const raw = valueEl.value.trim();
  const amount = Number(raw);
  if (!name) { say('Type a name for the expense.', 'err'); nameEl.focus(); return; }
  if (raw === '' || !Number.isFinite(amount) || amount < 0) { say('Type an amount of 0 or more.', 'err'); valueEl.focus(); return; }
  try {
    await tessera.call('data.patch', { operations: [{ op: 'add', collection: 'expenses', record: { name: name, amount: amount } }] });
    nameEl.value = '';
    valueEl.value = '';
    await load();
    say('Added ' + name + '.', 'ok');
    nameEl.focus();
  } catch (e) {
    say('Could not add the expense. Your entry is still here; try again.', 'err');
  }
}

async function removeItem(id) {
  const rev = revs.get(id);
  let label = '';
  for (const it of items) { if (it.id === id) label = it.name; }
  try {
    await tessera.call('data.patch', { operations: [{ op: 'remove', collection: 'expenses', id: id, revisionCount: rev }] });
    await load();
    say('Removed ' + label + '.', 'ok');
    nameEl.focus();
  } catch (e) {
    say('Could not remove ' + label + '. Try again.', 'err');
  }
}

document.getElementById('add').addEventListener('click', addItem);
for (const el of [nameEl, valueEl]) {
  el.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') addItem(); });
}
typeEl.addEventListener('change', render);
load().catch(() => say('Could not load your expenses.', 'err'));

